.cal-wrap {
  position: relative; margin-top: 14px;
  /* Deliberately shallow: the calendar is now the "pick your window" step that
     feeds the planner below it, so it stays compact and scrolls internally
     rather than pushing the Plan card off-screen. */
  max-height: 38vh; overflow-y: auto; overflow-x: hidden;
  border-radius: 10px;
}
.cal-inner { position: relative; }

.cal-sticky { position: sticky; top: 0; z-index: 4; background: var(--paper); }

.cal-row { display: grid; grid-template-columns: 190px 1fr 84px; gap: 0 14px; align-items: center; }

.cal-head { border-bottom: 1px solid var(--line); padding-bottom: 6px; }
.cal-head-right { font-size: 0.62rem; font-weight: 600; color: #98a2b3; text-align: center; line-height: 1.15; }
.days { display: grid; grid-template-columns: repeat(31, 1fr); gap: 3px; }
.day-col { text-align: center; line-height: 1.15; }
.day-dow { display: block; font-size: 0.56rem; font-weight: 600; color: #b0b7c3; }
.day-num { display: block; font-size: 0.7rem; font-weight: 600; color: var(--muted); font-variant-numeric: tabular-nums; }
.day-col.wknd .day-num { color: var(--ink); font-weight: 700; }
.day-col.pre .day-num, .day-col.pre .day-dow { color: #cfd4de; }

.lanes { position: relative; z-index: 1; }
/* One tight single-line row per show — this screen is an overview of the shows
   you want, so each row is deliberately compact (title only, no meta line). */
.lane { min-height: 22px; padding: 1px 0; border-bottom: 1px solid #f1f2f6; }
.lane:last-child { border-bottom: none; }
.lane-label { min-width: 0; display: flex; align-items: center; gap: 4px; }
.lane-title {
  font-family: var(--display); font-weight: 600; font-size: 0.8rem; line-height: 1.2;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
/* The must-see pin — hidden unless the row is forced into the plan. */
.lane-pin { flex: 0 0 auto; font-size: 0.72rem; display: none; }
.lane--forced .lane-pin { display: inline; }
/* A scheduled row gets a faint green wash + accent so the grid mirrors the plan. */
.lane--scheduled { background: rgba(5, 150, 105, 0.05); box-shadow: inset 3px 0 0 var(--ok); }
/* The name and the performance marks are the two click targets (pin the show /
   pin that performance). Everything else keeps the normal cursor. */
.lane-label { cursor: pointer; }
.lane-label:hover .lane-title { text-decoration: underline; }
.lane-track { display: grid; grid-template-columns: repeat(31, 1fr); gap: 3px; align-items: center; height: 100%; }

/* A day cell holds one coloured segment per performance; two performances on a
   day render as two side-by-side segments — the split IS the "two shows that
   day" cue. Single-performance days read as one solid bar. */
.cell { height: 10px; border-radius: 3px; display: flex; gap: 0; overflow: hidden; cursor: pointer; }
.cell:hover { box-shadow: 0 0 0 2px rgba(16, 24, 40, 0.3); }
.cell-multi { gap: 1.5px; }
.seg { flex: 1 1 0; min-width: 0; border-radius: 3px; }
/* The pinned performance: a solid inset ring (inset so the cell's overflow:hidden
   doesn't clip it), legible on any segment colour. */
.seg--pinned { box-shadow: inset 0 0 0 2px var(--ink); }
.seg-avail   { background: var(--fr-avail); }
.seg-2for1   { background: var(--fr-2for1); }
.seg-preview { background: var(--fr-preview); }
.seg-free    { background: var(--fr-free); }
.seg-event   { background: var(--fr-event); }
.seg-noalloc { background: var(--fr-noalloc); }
.seg-sold    { background: var(--fr-sold-bg); box-shadow: inset 0 0 0 1.5px var(--fr-sold-line); }

.lane-status { font-size: 0.72rem; line-height: 1.2; text-align: center; }
.lane-status .st-plan {
  font-weight: 700; color: var(--ok-text); white-space: nowrap;
  background: var(--ok-bg); border-radius: 999px; padding: 2px 7px;
}
.lane-status .st-in { color: var(--violet-dark); font-weight: 600; white-space: nowrap; }
.lane-status .st-no { color: #c2c8d2; font-weight: 700; }
/* A show with nothing catchable in the window recedes as a whole. But a
   scheduled or forced row is never dimmed — it made the plan. */
.lane--out:not(.lane--scheduled) .lane-title { opacity: 0.42; }
.lane--out:not(.lane--scheduled) .lane-track { opacity: 0.35; }

/* --- Window controls: the rail (sticky, above the day header) --- */
/* All dragging lives here: the two handle tabs resize the window; the space
   between them slides the whole window. */
.win-rail { position: relative; height: 38px; }
.rail-band {
  position: absolute; top: 6px; bottom: 0;
  background: rgba(108, 76, 241, 0.07);
  border-radius: 8px 8px 0 0;
  cursor: grab; touch-action: none;
}
.rail-band:active { cursor: grabbing; }
/* A centred grip bar so the between-space reads as draggable. */
.rail-band::before {
  content: ""; position: absolute; left: 50%; top: 50%;
  transform: translate(-50%, -50%);
  width: 26px; height: 4px; border-radius: 2px;
  background: rgba(108, 76, 241, 0.35);
}
.rail-band:hover::before { background: rgba(108, 76, 241, 0.6); }

.win-handle {
  position: absolute; top: 0; bottom: 0; width: 26px;
  transform: translateX(-50%);
  cursor: grab; touch-action: none; z-index: 1;
}
.win-handle:active { cursor: grabbing; }
/* The tab's stem: a short violet line down to the day header, continuing
   visually into the band edge below the header. */
.win-handle::before {
  content: ""; position: absolute; left: 50%; top: 6px; bottom: 0;
  width: 2px; margin-left: -1px; background: var(--violet);
}
/* The draggable knob. A raised pill button with a grip on its outer edge, so it
   reads as grab-and-slide rather than a static date label. Tabs anchor OUTWARD
   from their stem (start points left, end points right) so they never collide
   even when the window is dragged narrow. The "0 2px 0" layer is a solid bottom
   edge that gives the button height; the press state below sinks it. */
.win-flag {
  position: absolute; top: 2px;
  display: inline-flex; align-items: center; gap: 8px;
  font-size: 0.72rem; font-weight: 700; color: var(--violet-dark);
  background: linear-gradient(#ffffff, #f1ecff);
  border: 1.5px solid var(--violet); border-radius: 9px;
  padding: 6px 11px; white-space: nowrap;
  box-shadow: 0 2px 0 rgba(90, 63, 214, 0.35), 0 5px 12px rgba(16, 24, 40, 0.18);
  font-variant-numeric: tabular-nums;
  cursor: grab;
  transition: transform 0.08s ease, box-shadow 0.08s ease, background 0.12s ease, color 0.12s ease;
}
.win-handle--start .win-flag { right: 50%; margin-right: -2px; }
.win-handle--end .win-flag { left: 50%; margin-left: -2px; }
/* Grip bars inherit the flag's text colour (violet → white on hover). */
.win-flag .grip { display: inline-flex; gap: 2.5px; }
.win-flag .grip i { width: 3px; height: 14px; border-radius: 2px; background: currentColor; opacity: 0.55; display: block; }
.win-handle:hover .win-flag, .win-handle:focus-visible .win-flag {
  background: var(--violet); color: #fff; border-color: var(--violet);
  transform: translateY(-1px);
  box-shadow: 0 3px 0 rgba(90, 63, 214, 0.5), 0 9px 18px rgba(16, 24, 40, 0.24);
}
/* Pressed: sink the button and flatten its edge for a tactile grab. */
.win-handle:active .win-flag {
  transform: translateY(1px);
  box-shadow: 0 1px 0 rgba(90, 63, 214, 0.4), 0 3px 8px rgba(16, 24, 40, 0.18);
}
.win-handle:focus-visible { outline: none; }
.win-handle:focus-visible .win-flag { box-shadow: 0 0 0 3px rgba(108, 76, 241, 0.35), 0 5px 12px rgba(16, 24, 40, 0.18); }

