input.new_string:
.seg { flex: 1 1 0; min-width: 0; border-radius: 3px; }
/* The performance the plan actually *set* for this show — the grid mirrors the
   itinerary, ringing the chosen day/time (inset so the cell's overflow:hidden
   doesn't clip it), in the same green as the "In plan" status. */
.seg--selected { box-shadow: inset 0 0 0 2px var(--ok); }
/* A whole-show pin: every performance gets a dashed green border (you've forced
   the show in; the scheduler still picks which one, and that one goes solid via
   .seg--selected). Outline — not box-shadow — so it can be dashed; the negative
   offset pulls it inside the mark so the cell's overflow:hidden doesn't clip it. */
.seg--forced-all { outline: 1.5px dashed var(--ok); outline-offset: -1.5px; }
/* A pinned exact performance: the same solid green ring, plus a pushpin badge
   that sits above the mark. The badge deliberately overlaps the row above, so
   the pinned cell drops its overflow clip to let it escape upward. */
.seg--pinned { box-shadow: inset 0 0 0 2px var(--ok); position: relative; }
.cell--pin { overflow: visible; }
.seg-pin {
  position: absolute; left: 50%; bottom: 100%;
  transform: translate(-50%, 30%);
  font-size: 0.82rem; line-height: 1; pointer-events: none; z-index: 6;
  filter: drop-shadow(0 1px 1px rgba(16, 24, 40, 0.35));
}

