ls data/normalized/ 2>/dev/null && echo "---" && node -e "
const fs=require('fs');
const shows=JSON.parse(fs.readFileSync('data/normalized/shows.json','utf8'));
// pick shows with several performances in early-mid August, spanning statuses & doubles
const arr=Array.isArray(shows)?shows:shows.shows||[];
console.log('total shows', arr.length);
const pick=arr.filter(s=>(s.performances||[]).filter(p=>p.date>='2026-08-07'&&p.date<='2026-08-22').length>=5).slice(0,8);
for(const s of pick) console.log(s.slug, '|', s.title, '|', (s.performances||[]).length);
"

