input.content:
import { chromium } from '/opt/node22/lib/node_modules/playwright/index.mjs';
const OUT = '/tmp/claude-0/-home-user/f07b3322-5267-5aae-ac1e-5874e52d6c35/scratchpad';
const browser = await chromium.launch();

async function run(width, tag) {
  const ctx = await browser.newContext({ viewport: { width, height: 900 }, deviceScaleFactor: 2 });
  const page = await ctx.newPage();
  page.on('console', m => { if (m.type() === 'error') console.log('PAGE ERR:', m.text()); });
  await page.goto('http://localhost:8000/plan/', { waitUntil: 'domcontentloaded' });
  const input = await page.$('#csvInput');
  await input.setInputFiles(OUT + '/favs.txt');
  await page.waitForSelector('.lane', { timeout: 15000 });
  await page.waitForTimeout(900);

  // Pin one exact performance: click a seg in the 2nd lane.
  const lanes = await page.$$('.lane');
  const laneForPerf = lanes[2];
  const segs = await laneForPerf.$$('.seg');
  if (segs.length) await segs[Math.min(3, segs.length - 1)].click();
  // Pin a whole show: click the label (name) of the 4th lane.
  const laneForShow = lanes[4];
  await (await laneForShow.$('.lane-label')).click();
  await page.waitForTimeout(700);

  await page.screenshot({ path: `${OUT}/${tag}-full.png`, fullPage: false });
  const cal = await page.$('#calWrap');
  await cal.screenshot({ path: `${OUT}/${tag}-cal.png` });
  const sched = await page.$('.schedule-wrap');
  if (sched) await sched.screenshot({ path: `${OUT}/${tag}-sched.png` });
  console.log(tag, 'lanes:', lanes.length,
    'selected:', await page.$$eval('.seg--selected', e => e.length),
    'pinned:', await page.$$eval('.seg--pinned', e => e.length),
    'forced-all:', await page.$$eval('.seg--forced-all', e => e.length),
    'badges:', await page.$$eval('.seg-pin', e => e.length),
    'status-pins:', await page.$$eval('.st-pin', e => e.length));
  await ctx.close();
}

await run(1280, 'wide');
await run(760, 'narrow');
await browser.close();
console.log('done');

