import { chromium } from '/opt/node22/lib/node_modules/playwright/index.mjs';
const OUT = '/tmp/claude-0/-home-user/f07b3322-5267-5aae-ac1e-5874e52d6c35/scratchpad';
const browser = await chromium.launch();
const ctx = await browser.newContext({ viewport: { width: 1180, height: 1000 }, deviceScaleFactor: 2 });
const page = await ctx.newPage();
await page.goto('http://localhost:8000/plan/', { waitUntil: 'domcontentloaded' });
await (await page.$('#csvInput')).setInputFiles(OUT + '/favs-many.txt');
await page.waitForSelector('.lane', { timeout: 15000 });
await page.waitForTimeout(600);
// widen the date window to the max and set max-per-day to 1 so the plan spreads
// across many day columns (stresses the schedule width).
await page.evaluate(() => {
  const sel = document.querySelector('#maxPerDay') || document.querySelector('[id*="max" i]');
  return sel && sel.tagName;
});
// Try to set max-per-day to 1 via its select if present.
const maxSel = await page.$('#maxPerDay');
if (maxSel) { await maxSel.selectOption('1').catch(()=>{}); }
await page.waitForTimeout(600);
const days = await page.$$eval('.sch-day', e => e.length);
const wrap = await page.$('.schedule-wrap');
const metrics = await wrap.evaluate(el => ({ scrollW: el.scrollWidth, clientW: el.clientWidth }));
console.log('sch-days:', days, 'scrollW:', metrics.scrollW, 'clientW:', metrics.clientW,
  'overflow:', metrics.scrollW > metrics.clientW + 1);
await wrap.screenshot({ path: OUT + '/many-sched.png' });
await browser.close();
console.log('done');

