import { chromium } from '/opt/node22/lib/node_modules/playwright/index.mjs';
const OUT = '/tmp/claude-0/-home-user/f07b3322-5267-5aae-ac1e-5874e52d6c35/scratchpad';
const browser = await chromium.launch();
const ctx = await browser.newContext({ viewport: { width: 760, height: 900 }, deviceScaleFactor: 1 });
const page = await ctx.newPage();
await page.goto('http://localhost:8000/plan/', { waitUntil: 'domcontentloaded' });
await (await page.$('#csvInput')).setInputFiles(OUT + '/favs-many.txt');
await page.waitForSelector('.lane', { timeout: 15000 });
await page.waitForTimeout(500);
const offenders = await page.evaluate(() => {
  const vw = document.documentElement.clientWidth;
  const out = [];
  for (const el of document.querySelectorAll('*')) {
    const r = el.getBoundingClientRect();
    if (r.right > vw + 1 && r.width > 0) {
      out.push({
        tag: el.tagName.toLowerCase(),
        cls: (el.className && el.className.toString().slice(0, 40)) || '',
        id: el.id || '',
        right: Math.round(r.right), width: Math.round(r.width),
      });
    }
  }
  // keep the widest few, deepest offenders
  return out.sort((a, b) => b.right - a.right).slice(0, 12);
});
console.log(JSON.stringify(offenders, null, 1));
await browser.close();

