import { chromium } from '/opt/node22/lib/node_modules/playwright/index.mjs';
const browser = await chromium.launch();
const ctx = await browser.newContext({ viewport: { width: 1280, height: 800 }, deviceScaleFactor: 1 });
const page = await ctx.newPage();
await page.goto('http://localhost:8000/plan/', { waitUntil: 'domcontentloaded' });
await page.waitForTimeout(300);
const info = await page.evaluate(() => {
  const inner = document.querySelector('.header-inner');
  const cs = getComputedStyle(inner);
  const items = [...inner.children].map(el => ({
    cls: el.className, w: Math.round(el.getBoundingClientRect().width),
  }));
  const gap = cs.gap;
  const sum = items.reduce((a, b) => a + b.w, 0);
  return { gap, items, sum, count: items.length };
});
console.log(JSON.stringify(info, null, 1));
await browser.close();

